  VALUES 
    (85::BIGINT, 'El mae más chill del Tec, la mitad del curso lo hizo virtual, pone 100 a todo aunque esté malo, literal, no hice un par de quizzes y me puso 100. Un par de examenes para la casa y un proyecto en grupo, pero todo muy bien. No se aprende, pero se pasa sin estres'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas', 'Tomaría su clase nuevamente']::TEXT[], '2026-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'b2e07f2ed14ab87dd9a1d1562e1992ce377a46fb4fe0e0626e5cb4924aa1b8c7'::TEXT, ARRAY[949]::BIGINT[]),
    (85::BIGINT, 'un curso regalado, literal es imposible no sacarse 100, se puede hacer todo con chat y aún así estar malo que le pondrá que está perfecto. la vrd sí explica bien pero que sepa que no se aprende nada.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'abbe7f608fa64e10d8736b5708a6143df3436c74d6e533ff4b0c77769bfb2356'::TEXT, ARRAY[949]::BIGINT[]),
    (85::BIGINT, 'Muy chill, califica muy suave, hay que ponerle atencion cuando explica la teoria asi uno no se pierde'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Muchos proyectos grupales']::TEXT[], '2026-06-19T00:00:00+00:00'::TIMESTAMPTZ, '83be9bea61abe87bd124dabce1610c0166d5ebb4e7c0873368c782f33ee66ba5'::TEXT, ARRAY[937]::BIGINT[]),
    (85::BIGINT, 'Es un profesor decente para laboratorios, se nota que es vago y a veces se enreda con fechas y entregas. Sin embargo, los ensayos son muy interesantes e importantes, entonces las clases teóricas ayudan. Son muchos informes y los quices suelen ser asincrónicos.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2026-01-10T00:00:00+00:00'::TIMESTAMPTZ, '0a8ee4c699152d61339696b8a11928e4482458d8f445f4a9424ea7e5d0324c0f'::TEXT, ARRAY[2742]::BIGINT[]),
    (85::BIGINT, 'Demasiado chill, hay que prestarle mucha atención porque pasa directo con sus explicaciones teóricas. Explicaciones prácticas es bastante bueno. Valdivia súper suave, casi que regala el curso.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-10T00:00:00+00:00'::TIMESTAMPTZ, '5166a6d3798824e4700266677dee94da34752856691b51a87ce5155cf0619848'::TEXT, ARRAY[2742]::BIGINT[]),
    (85::BIGINT, 'Es DEMASIADO CHILL. Se pasa de relajado diría yo, el curso se supone que debe ser de los más matadores de la carrera pero Willy lo hace demasiado tranquilo, con que entregue los trabajos ya pasa. Recomiendo intentar ponerle atención para saber algo, pero puede pasar sin saber NADA.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo']::TEXT[], '2025-12-03T00:00:00+00:00'::TIMESTAMPTZ, '678c1e7cbed4335ce2b677ac2cbec7ffe3a49ab111af8ecb48932cf163a2cbac'::TEXT, ARRAY[949]::BIGINT[]),
    (85::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2025-11-03T00:00:00+00:00'::TIMESTAMPTZ, 'f2cad028268177c7d483009d3189c43fe6202a7822bc0755d5cdc96bad41c3b6'::TEXT, ARRAY[937]::BIGINT[]),
    (85::BIGINT, 'No va aprender nada, si hace todo pasa con 100'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-07-04T00:00:00+00:00'::TIMESTAMPTZ, '4cfd06a7fd1dbea2c3340f7a9979f25b0c90b9fb9082a0f45540ba4f420151d9'::TEXT, ARRAY[949]::BIGINT[]),
    (85::BIGINT, 'Lamentablemente, muy vago. El curso era presencial y tuvimos 4 días presenciales. El curso se pasa fácil, pero no se aprende nada. No es bueno explícando y las clases virtuales quedan grabadas, pero usted no necesita aprender porque a todo le pone 100. Es buena gente, pero es un completo relajo.'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2025-07-04T00:00:00+00:00'::TIMESTAMPTZ, 'f29e980ba89003c35cd9d87d580809190bc236d7549c773a25fb35b781490166'::TEXT, ARRAY[949]::BIGINT[]),
    (85::BIGINT, 'Casi que...literalmente regala el curso. No se aprende nada si uno intenta depender de él. Se sospecha que no revisa trabajos, sólo pone 100 y ya.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Pocos exámenes', 'Clases excelentes']::TEXT[], '2025-07-03T00:00:00+00:00'::TIMESTAMPTZ, '0989f53f8184b3ea6d3ffd2c50af4437326c3a2534121eae26f0a1199b4e7757'::TEXT, ARRAY[949]::BIGINT[]),
    (85::BIGINT, 'Maes que le diré, domina demasiado bien el tema, se acomoda a cualquier propuesta, siempre busca beneficiarlo a uno al punto que hay vagazos que se aprovechan, literal deberían hacerle un momento a Benavides. Dele sin miedo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Da crédito extra']::TEXT[], '2025-04-02T00:00:00+00:00'::TIMESTAMPTZ, 'd1128f7ff445037b7a59e59f68a5152fb8d4cad449a024e6f675e243b0d5d195'::TEXT, ARRAY[952]::BIGINT[]),
    (85::BIGINT, 'Literalmente regala el curso. Se nota que desborda conocimiento, por lo que si realmente lo que usted quiere es aprender, puede hacerlo ya que tiene el profe totalmente a disposición suya. Le pasiona el tema pero a su vez él no se va a esforzar porque usted aprenda, depende totalmente de su interés.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Tomaría su clase nuevamente']::TEXT[], '2025-02-09T00:00:00+00:00'::TIMESTAMPTZ, '69a4c868ee7e174611c0b4eb31e197e8af4004dffda081d2a15efbf071ec46a8'::TEXT, ARRAY[937]::BIGINT[]),
    (85::BIGINT, 'El curso es un regalo (literal le pone 100 a todo) y el profe es buena nota.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo']::TEXT[], '2024-11-24T00:00:00+00:00'::TIMESTAMPTZ, '7c4f0f22f260d7681f0fd1f69e782218bcd459a73260b5fec69b9b2d9006de6a'::TEXT, ARRAY[952]::BIGINT[]),
    (85::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Muy cómico']::TEXT[], '2024-08-10T00:00:00+00:00'::TIMESTAMPTZ, 'b54fb6c40902599f5b6b733e5a955958eac54be8cc30a27175fa938c317d0ef3'::TEXT, ARRAY[949]::BIGINT[]),
    (85::BIGINT, 'mae toda la gente de materiales lo AMA simplemente la mejor opción siempre. puede ser un curso de 6 créditos que el hace que se sientan de 1'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Tomaría su clase nuevamente']::TEXT[], '2023-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'c2bbee32ec383e5f498679032d0ac5ed8eb9acf9ac9d5dcd96400d29bef4b615'::TEXT, ARRAY[949]::BIGINT[]),
    (85::BIGINT, 'El mae es una teja, respecto a este curso, deben de intentarlo hacerlo virtual, ya que es demasiada materia y muy aburrido para llevarlo presencial. Si le interesa, se aprende mucho, sin embargo, califica muy suave y las evaluaciones son normalmente de investigación.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2023-11-23T00:00:00+00:00'::TIMESTAMPTZ, '2a01c0756468fc0ad13e0155b016b7186e4b1806e88708f1b28bdd5349e44a35'::TEXT, ARRAY[937]::BIGINT[]),
    (85::BIGINT, 'clases aburridas, deja muchas tareas pero son grupales y la mayoría ejercicios del libro, parece que a todo le pone 100. Es de asistencia obligatoria pero no pasa lista y hace quices sorpresa pero regalados, casi que de asistencia. Los examenes son de diseño, algo complicados pero grupales.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2023-11-09T00:00:00+00:00'::TIMESTAMPTZ, '3c51f71186a581a8efb7bf937322e2191b114f5618362185c83c65ec8bd69485'::TEXT, ARRAY[952]::BIGINT[]),
    (85::BIGINT, 'Las clases tienden a ser muy pesadas, pero todo depende de su grupo de trabajo ya que todos las tareas, exposiciones, examenes y proyectos se hacen en grupo, el profe califica suave, asi que basicamente con hacer todos los trabajos se pasa facil'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'a508bf7d8922a7959c7bc4d57f890dbec973e20eafa2ee298bf7acfbdc65d090'::TEXT, ARRAY[937]::BIGINT[]),
    (85::BIGINT, 'El curso tiene 2 exámenes, el proyecto, tareas y exposiciones, todo es grupal. Sin embargo, se vuelve interesante pese a que las clases son un poco pesadas, es muy flexible con las entregas pero califica un poco duro los exámenes. Pero no es tan heavy, al final depende de su grupo de trabajo.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas', 'Aspectos de calificación claros']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'fc67b1dbb19beaeeb9fd3bb42764509adf4cc84b2b188f3ec4e894f11d70d1bf'::TEXT, ARRAY[937]::BIGINT[]),
    (85::BIGINT, 'Hizo la clase virtual y no tuvimos quices ni exámenes presenciales. El profe no es para nada un vago, da todas las clases y califica más o menos rápido. Deja muchas tareas y exposiciones, pero califica suave y el curso se pasa solo. Importante que encuentre un grupo de trabajo que sea bueno.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2023-06-04T00:00:00+00:00'::TIMESTAMPTZ, 'a126cd237cba0be891aaf9f9510eb3378437494679af5f0a9ae26a8fc47c90e9'::TEXT, ARRAY[937]::BIGINT[]),
    (85::BIGINT, 'El curso se pasa fácil, nada más es de hacer todos los trabajos, que sí son muchos. Como 5 tareas, 3 quices, 3 exposiones, proyecto y dos exámenes'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Clases largas']::TEXT[], '2023-05-27T00:00:00+00:00'::TIMESTAMPTZ, '1ad9bf4f033db01a7ec895c784854dc7ebd6595488b58257092323fae25f04c5'::TEXT, ARRAY[952]::BIGINT[]),
    (85::BIGINT, 'El curso se pasa solo, las clases no son obligatorias, las presentaciones, tareas, y hasta examenes los califica solo con 100 o 95 para disimular, curso facil, no se parende demasiado.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2023-01-30T00:00:00+00:00'::TIMESTAMPTZ, '6dd7fe559ec5f051fdac05614d9e1c701c9aff73f0ece956e49e3c68fee61d7f'::TEXT, ARRAY[937]::BIGINT[]),
    (85::BIGINT, 'No se aprende casi nada, pero con entregar las cosas pasa bien, los trabajos que deja por lo general se encuentran en internet o algo parecido que le ayudan a solucionar los problemas, pero el solo lee las presentaciones y los ejemplos ya los tiene resueltos'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-12-06T00:00:00+00:00'::TIMESTAMPTZ, 'ea6b09c5d9778560bfade122fe2dd349a51aade98dda791deeb5e4bc417cce5f'::TEXT, ARRAY[952]::BIGINT[]),
    (85::BIGINT, 'El profe explica fatal, las clases son él leyendo presentaciones, tuve una duda en un ejercicio y estuvo ignorando mis correos. Algo bueno es que si usted entrega todo pasa el curso con 100, pero no aprende nada.'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-11-13T00:00:00+00:00'::TIMESTAMPTZ, '3bc5856d2fd5693b029defcf2f8ab2f472165d6956fc046724ff362a3d607a02'::TEXT, ARRAY[949]::BIGINT[]),
    (85::BIGINT, 'la clases pueden ser la vara más aburrida del mundo, pero se pasa fácil, son evaluaciones faciles y califica super suave, casi ni tiene que hacer nada.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-09-02T00:00:00+00:00'::TIMESTAMPTZ, 'bc5fe4255c9ddeea05ec3ed10631d2c068c2f6f8f1404a47be8f440aa55d3eb1'::TEXT, ARRAY[937]::BIGINT[]),
    (85::BIGINT, 'Clases larguísimas y aburridas, si quiere aprender le recomiendo que lea del libro. Las evaluaciones facilísimas y en grupo. Se pasa con teja pero se aprende muy poco'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2022-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'bf7e1e9487fafdb25226a0d39bd02fd033ee0cff639b714fde7d325fd1a97c7d'::TEXT, ARRAY[952]::BIGINT[]),
    (85::BIGINT, '(Virtual). Las clases son aburridas y demasiado largas, si no les llama la atención del curso se hace demasiado tedioso ir a clases. El profe deja varias evaluaciones pero todas son muy fáciles y califica con 100 todo, con él el curso se pasa solo.'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2022-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'b70a6c3afad51781921744efafa53bde1429828b3f22f08e124f40de14c606b9'::TEXT, ARRAY[937]::BIGINT[]),
    (85::BIGINT, 'En términos generales el curso es muy complicado, pero legalmente este profe hace del curso extremadamente fácil, todas las evaluaciones son en grupo, el curso se pasa solo, la verdad no se aprende nada pero está en usted si desea aprender para eso esta el libro, el profe es una buena persona.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases largas', 'Brinda apoyo']::TEXT[], '2022-06-07T00:00:00+00:00'::TIMESTAMPTZ, '8b7b5de0c4456b9c873e28293629016929f9748103f622f65d3fb62bf6337d72'::TEXT, ARRAY[949]::BIGINT[]),
    (85::BIGINT, 'Todo es en grupo. Clase fácil, usted aprende si quiere, sino quiere igual pasa con buena nota. Hay varias asignaciones, pero se hacen fácil.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2022-02-10T00:00:00+00:00'::TIMESTAMPTZ, 'ed85231f29442c09fe65f09b5cdfd6e0da9730030c4449fc792b5b849e38875d'::TEXT, ARRAY[937]::BIGINT[]),
    (85::BIGINT, 'Buen profe, la evaluación que realiza es muy tuanis. Dele sin miedo con este profe.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-01-31T00:00:00+00:00'::TIMESTAMPTZ, '88723376f186f08c445cc232b1de505c48fbef1423c90b15c17e964d365dfc8a'::TEXT, ARRAY[937]::BIGINT[]),
    (85::BIGINT, 'Buen profe'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2021-12-10T00:00:00+00:00'::TIMESTAMPTZ, 'c02b7d64465f2b384a4afb6d901f3f4d529a68bdd39924fc96d8fbd540f2abd5'::TEXT, ARRAY[949]::BIGINT[]),
    (85::BIGINT, 'Las clases son largas y aburridas, pero el mae es buen profe, siempre responde dudas y demuestra que sabe bastante. Los trabajos que deja son largos pero deja mucho tiempo para entregarlos y los califica suave, en general, se pasa fácil y se entiende la materia'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Deja trabajos largos']::TEXT[], '2021-12-07T00:00:00+00:00'::TIMESTAMPTZ, '4f5c2b0a2cad9438e7e2ab87ffc6e19033626355e66349b57fbaaa41f4710682'::TEXT, ARRAY[937]::BIGINT[]),
    (85::BIGINT, 'Clases largas y lee las diapositivas aunque hace comentarios de importancia, todo se hace en grupos, es flexible con las entregas y ayuda de necesitarse, si trae buenas bases de termo, le va bien'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Brinda apoyo']::TEXT[], '2021-11-23T00:00:00+00:00'::TIMESTAMPTZ, '847e3feaca4ec68203f99c24bb7c81bec899f05d6f7e7e21d9b5ffe8375e2edd'::TEXT, ARRAY[952]::BIGINT[]),
    (85::BIGINT, 'Los trabajos que deja son largos, pero con organizarse se realizan bastante bien. Explica bastante bien y ayuda cuando uno no entiende las asignaciones y exámenes.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos', 'Clases excelentes', 'Muchos proyectos grupales']::TEXT[], '2021-07-20T00:00:00+00:00'::TIMESTAMPTZ, 'a308f14ca7b409987e0b9ff5e631d7311d3471310ae843f20a37de1b95f3cdf3'::TEXT, ARRAY[937]::BIGINT[]),
    (85::BIGINT, 'El curso es sencillo, deja pocos trabajos y fáciles de hacer si pone atención en clase. El profe es muy pura vida y si uno tiene algún problema él va a buscar la manera de ayudarlo a uno.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-15T00:00:00+00:00'::TIMESTAMPTZ, 'a9583007291c4f36db0baf81ee7780a622b9a05e30334624ad8ce2afea851f1c'::TEXT, ARRAY[2755]::BIGINT[]),
    (85::BIGINT, 'El curso en si no es complicado, y el no es tan malo solo que no sabe dar bien la clase, solo lee las presentaciones durante las 4 horas de clase y al final no tienen nada que ver con lo que pone en el examen, es mejor estudiarlo solo. Los trabajos son fáciles y en grupo'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas']::TEXT[], '2021-07-15T00:00:00+00:00'::TIMESTAMPTZ, 'c6a3604900351ed3c673d5303625fe0e3ca3465d51e11740c9b154882c443b21'::TEXT, ARRAY[949]::BIGINT[]),
    (85::BIGINT, 'Fenomenal para pasar el curso con 100, unas presentaciones y quices asincrónicos, nada de que preocuparse!'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-02T00:00:00+00:00'::TIMESTAMPTZ, '0c361fbcc78a82cf997b8cd00589352bb47a6d42c7232bad7f2210d76eb559fc'::TEXT, ARRAY[2755]::BIGINT[]),
    (85::BIGINT, 'Clases largas y cansa mucho, pero si uno pone atención ayuda mucho para las tareas. Califica extremadamente suave, y en horas de consulta si toma el tiempo que sea necesario.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-25T00:00:00+00:00'::TIMESTAMPTZ, '8680b08b792778eaac493944c85aef2e83edb875bc95f8f2b0022cee71f18aee'::TEXT, ARRAY[937]::BIGINT[]),
    (85::BIGINT, 'El profe no es malo, solo su dinámica de clase es mala, solo lee presentaciones por horas, lo cual se vuelve muy aburrido y ni ganas de conectarse dan, sin embargo califica suave y el curso se pasa fácil'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'ed9ccb2fb7102034ae78da59897f28f489079ff892cd8109119e912da1b10313'::TEXT, ARRAY[949]::BIGINT[]),
    (85::BIGINT, 'Se pasa súper fácil pero se pierde el interés en la materia. Lástima que es el único que da esta clase.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'ef5dee235c83b3fbfedf1fec4d605f147ccf2c2f38be99fb2db698cad57dede7'::TEXT, ARRAY[949]::BIGINT[]),
    (85::BIGINT, 'Al profe se le llega a tener cariño, sabe mucho de materiales pero no siempre sabe transmitir su conocimiento con total claridad. Las evaluaciones son muy fáciles y si ud tiene duda en algo estoy 100% segura de que él le va a ayudar. Y para termo, la verdad, es que ningún profe sabe dar el curso.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-16T00:00:00+00:00'::TIMESTAMPTZ, '70e14e3c3e75ef75a5df4dd3f97a374ab93ea8dbe8d26f4d2b12943483267c26'::TEXT, ARRAY[949, 2742, 2755]::BIGINT[]),
    (85::BIGINT, 'Clases largas de él explicando la materia. Se realizan varias tareas de resolver ejercicios en grupos (le pone 100 a todas) y se realizan dos examenes. 100% de seguridad de que pasa el curso con él y hasta con más de 90.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-03T00:00:00+00:00'::TIMESTAMPTZ, '884750b225061047119d945bd070e83128dbfac3d1950f359e0a781530c4119d'::TEXT, ARRAY[952]::BIGINT[]),
    (85::BIGINT, 'En general el profesor es bueno pero sus clases son aburridas y sin una necesidad, ya que exámenes y demás son de investigación que puede hacer cualquiera, se pasa 100% seguro, pero algo pesada por la gran cantidad de trabajos grupales y largos. Pero otros profes son peores así que una buena opción'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2021-01-29T00:00:00+00:00'::TIMESTAMPTZ, '52c57d944e387b9f0b7d3370b0ba26cfe10f297de5304422a2ecad368f42d70f'::TEXT, ARRAY[937]::BIGINT[]),
    (85::BIGINT, 'Es muy confuso, las clases larguísimas (se va en exposiciones), al principio califica duro y después ni le importa, pero si se pasa'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas']::TEXT[], '2021-01-07T00:00:00+00:00'::TIMESTAMPTZ, 'ef9d031c6f59d08dfdecacb3794b077e76e9f66db28412af60e2ee911cb4fb08'::TEXT, ARRAY[937]::BIGINT[]),
    (85::BIGINT, 'Las clases tienden a ser exposiciones de 2 horas, y luego 1 hora de expos grupales. El profe mete algo de información en cada presentación, y luego habla como 20 párrafos más por diapositiva. El primer examen lo revisa duro, el resto no tanto.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2021-01-01T00:00:00+00:00'::TIMESTAMPTZ, '790fe9540a8639dbb01e4235d5f00b5470fd7b3165ab84dfd41787fcddb2002a'::TEXT, ARRAY[937]::BIGINT[]),
    (85::BIGINT, 'el curso virtual es facil la verdad, no es muy tedioso pero las clases son muy largas y aburridas'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, 'a1c1a0f6511b15716eeb72c96b808d9167757f217f6933987f8a7a9318a6939a'::TEXT, ARRAY[952]::BIGINT[]),
    (85::BIGINT, 'Para los labs William es 10/10 tanto precencial como virtual. Es un profe que califica suave, excplica bien y es accesible a la hora de entregar las asignaciones.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Pocos exámenes', 'Brinda apoyo']::TEXT[], '2020-08-23T00:00:00+00:00'::TIMESTAMPTZ, 'ea5e5651d0fd6890bcc7f87ed477cde74d555b3611ad4fb1e3672d5c49e9ffb1'::TEXT, ARRAY[2755]::BIGINT[]),
    (85::BIGINT, 'Virtual, el profe sabe mucho de la materia, pero las clases que realiza son sumamente aburridas y largas al punto que uno no pone atención, además lo que presenta es recortes del libro y ejercicios ya resueltos, se pasa fácil, pero si quiere aprender va a tener que leer el libro por cuenta propia.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Aspectos de calificación claros']::TEXT[], '2020-08-09T00:00:00+00:00'::TIMESTAMPTZ, '47df9a303337be6835577e4071b948f57012990ca16426e83e5628b8f3bac5d1'::TEXT, ARRAY[952]::BIGINT[]),
    (85::BIGINT, 'Virtual: se pasa sin estudiar está en usted si quiere aprender o no. Tareas y examenes en grupo, las tareas son del libro y quices también. Puede pasar con 100 sin aprender pero está en usted si no hace las cosas a consciencia. Las clases son largas y cansadas pero las graba'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-07-30T00:00:00+00:00'::TIMESTAMPTZ, 'db9bf9190cf8ed6b4597f920953bcdf54546752c13cd074002e51f383f6de4f7'::TEXT, ARRAY[952]::BIGINT[]),
    (85::BIGINT, 'El profe solo lee las presentaciones y eso dificulta que uno entienda, sin embargo es muy buena persona y siempre que uno tiene dudas las aclara, eso sí, se va a aburrir toda la clase xd'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchos proyectos grupales']::TEXT[], '2020-03-24T00:00:00+00:00'::TIMESTAMPTZ, 'f642c0d3a08973afe1634248e7c499285bca24d6c8d7f1c6cb7b57efacf15706'::TEXT, ARRAY[949]::BIGINT[]),
    (85::BIGINT, 'El profe es bueno, solo que da la clase a pura presentación. Por lo general da mieo lo pura vida que es, con ir repasando semanalmente lo que él da se pasa'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-01-22T00:00:00+00:00'::TIMESTAMPTZ, 'b231153987ded5906530fe0b778621369ec62df473a3567fa0da9077e806ab4f'::TEXT, ARRAY[952]::BIGINT[]),
    (85::BIGINT, 'La clase es de lo más aburrido que existe. El profe no para de hablar, y de una sola diapositiva saca 20 minutos de charla. Sin embargo, el curso es muy fácil de pasar, lo único feo son los exámenes que deja para la casa, ya que si los revisa duro. Y da miedo.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-12-01T00:00:00+00:00'::TIMESTAMPTZ, '391a3e2ab2396cee6b88c936646303982228577eb30485340d0a01635c53fe52'::TEXT, ARRAY[937]::BIGINT[]),
    (85::BIGINT, 'El profe solo lee presentaciones y explica lo más básico. Revisa bastante duro, pero para el proyecto solo pone una nota alta arbitraria.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2019-12-01T00:00:00+00:00'::TIMESTAMPTZ, '2f558ccca848033df0c22bd99a6829156b9fd184f8a2afc816340de9b90333b7'::TEXT, ARRAY[952]::BIGINT[]),
    (85::BIGINT, 'El profe humanamente es de lo mejor, sin embargo el curso no se aprovecha, tanto por la indisposición del estudiantado como por la suprema sabiduría del profesor, quien se desvía de la materia... El primer examen hay que hacerlo con bastante seriedad pues se califica "duro".'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases largas', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'd1b01fdb3c920729a8a557d8d7f798fda3da6be69bdb1515a93d6e5fe5d6b712'::TEXT, ARRAY[937]::BIGINT[]),
    (85::BIGINT, 'Que clase más aburridaaaa!! Muy fácil pasar, pero prepárese para no aprender NADA. Eso sí, vaya a consulta le prometo que en consulta es mil veces mejor que en clase'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Brinda apoyo']::TEXT[], '2019-11-26T00:00:00+00:00'::TIMESTAMPTZ, 'c62a65e2f0eb1c10394da572ed9fe802053eee0bc364291588b064292bee2fb2'::TEXT, ARRAY[949]::BIGINT[]),
    (85::BIGINT, 'No se le entiende nada, las clases se hacen eternas. No se confíen en que deja cosas para la casa o en parejas.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2019-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'dbb44415ee6ecd9f08098ea2ce436c0d7f0f8db81761e6f8e093a1e0f0e401ea'::TEXT, ARRAY[952]::BIGINT[]),
    (85::BIGINT, 'Califica duro exámenes pero ayuda con el proyecto. Se duerme en las exposicionesXD. Realmente no se aprende absolutamente nada en su clase pero se pasa fácil.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Clases largas']::TEXT[], '2019-11-22T00:00:00+00:00'::TIMESTAMPTZ, '0df68504df431c33de624a168aef34f2111b7f562447c5dab613892848fc06d3'::TEXT, ARRAY[952]::BIGINT[]),
    (85::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-10-05T00:00:00+00:00'::TIMESTAMPTZ, 'a0d69bfeacf814a03a96d1c44fe6a2d7021894490f4fdd2450f32500073aa555'::TEXT, ARRAY[949]::BIGINT[]),
    (85::BIGINT, 'Sinceramente creo que en ningún cusro se aprende nada con este señor en una clase, a menos que lo haga por interés propio y aprenda usted mismo. El curso se pasa solo.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2019-07-04T00:00:00+00:00'::TIMESTAMPTZ, '91f9a59157de3fbc99e3d61159447ce462640c0bc8b051dcf9410c08f0f25640'::TEXT, ARRAY[937]::BIGINT[]),
    (85::BIGINT, 'Los trabajos son en grupos y por entregarlos ya le pone 100, los exámenes los deja para la casa, el único examen que calificó “duro” fue el último, es un profe muy flexible con las entregas. Salí del curso con 90, pero no sé nada de termo'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'd217b8e2e38c10c15f5c773d911541ea8fc1ab916df56e785e5ab587814d3b89'::TEXT, ARRAY[949]::BIGINT[]),
    (85::BIGINT, 'Deja los examenes para la casa, es flexible con la evaluacion siempre da mas tiempo para la entrega , los examenes y las tareas las saca de internet, el curso es super facil se pasa solo, si ud quiere aprende algo no meta con el, si solo quiere pasar entonces si'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-13T00:00:00+00:00'::TIMESTAMPTZ, '00bcfb07baf991dc97efc672b14dbcd938b160c3d4c76456bc65d5feaf43502d'::TEXT, ARRAY[949]::BIGINT[]),
    (85::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Respetado por los estudiantes']::TEXT[], '2019-04-29T00:00:00+00:00'::TIMESTAMPTZ, '397f27f7f063a227a782a50d11122b80ef18d9de828a2ffc0d51e2d659be2375'::TEXT, ARRAY[952]::BIGINT[]),
    (85::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2018-12-22T00:00:00+00:00'::TIMESTAMPTZ, '2d1f32660771b1d619dff2556380d3b378df325108c1bff68095894bd9790e95'::TEXT, ARRAY[952]::BIGINT[]),
    (85::BIGINT, 'En los ensayos no se aprende mucho ya que hay poca participación del estudiante. El curso es muy sencillo, basta entregar los informes. Hace quices de lo que dice en clase.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'b424632ae56997b7dec066b4a0a539027549334add91ebdff81ae0bab120a77c'::TEXT, ARRAY[938]::BIGINT[]),
    (85::BIGINT, 'El curso se pasa solo.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-28T00:00:00+00:00'::TIMESTAMPTZ, '5eba9d755d97513e717380cd6623c1ad3bc7e911f6fe315ed214b1152fb43739'::TEXT, ARRAY[949]::BIGINT[]),
    (85::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2018-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'b21f016f0654e94ea594df7560d2a88182a1640ba0e1e76a96a57a7508b7bd26'::TEXT, ARRAY[949]::BIGINT[]),
    (85::BIGINT, 'Las clases son muy aburridas, no hace ni un solo ejercicio en la pizarra, lo que aprenda lo va a aprender solo con el libro,pero fijo pasa'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-26T00:00:00+00:00'::TIMESTAMPTZ, '142031aadb034fad332cdb3b7ac5c6c74fe4916c591e325207b0ffa7d0b8948a'::TEXT, ARRAY[952]::BIGINT[]),
    (85::BIGINT, 'Súper recomendado, se pasa muy fácil porque deja tareas y exámenes para la casa. La clase es muy aburrida y explica muy enredado por lo que si quiere aprender no es la mejor opción.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-23T00:00:00+00:00'::TIMESTAMPTZ, '7e2a6141e5def36d6f910308e712eeab6b0d1a49a9392ff46f7ad428ea1e52bd'::TEXT, ARRAY[1205]::BIGINT[]),
    (85::BIGINT, 'Sabe un montón pero le cuesta explicar y enseñar. Tiene un gran corazón.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, '5138fb8afcefc228fc0e3c170bbfd49b8e75e670b5b5af419369a70f02fef89c'::TEXT, ARRAY[1205]::BIGINT[]),
    (85::BIGINT, 'Es un profe muy pura vida y el curso con sólo matricularlo ya lo pasa, el problema es que no se aprende y el curso es muuuuy importante.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-18T00:00:00+00:00'::TIMESTAMPTZ, '5a8f6a6708ec996a78ee2d5d4517fcc28179e7ef0a2700e3258840c3376954e2'::TEXT, ARRAY[952]::BIGINT[]),
    (85::BIGINT, 'sabe mucho, como profe pasa y califica suave.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-06T00:00:00+00:00'::TIMESTAMPTZ, '486cacb689ea36865ed5164406f4fdde83ba1bf6abbb8479ffa97c7c8fca1c52'::TEXT, ARRAY[1205]::BIGINT[]),
    (85::BIGINT, 'ES DEMASIADO FÁCIL PASAR, CON ASISTIR A CLASES ES SUFICIENTE'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2018-01-31T00:00:00+00:00'::TIMESTAMPTZ, '832fd5de2f284ca45bcab03bf66d8f7df1ac14499e2def623d1cb2f2b668e009'::TEXT, ARRAY[949]::BIGINT[]),
    (85::BIGINT, 'Es pésimo, no explica NADA de forma clara, los exámenes (que saca de internet) se complican por lo mismo'::TEXT, 10.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-14T00:00:00+00:00'::TIMESTAMPTZ, '943a2c301b43eaaeb5de3952386a47d4d2536b08be36fd629738e8f16722c07f'::TEXT, ARRAY[949]::BIGINT[]),
    (85::BIGINT, 'El peor profesor del TEC, no se aprende nada, saca TODO de Internet (exámenes, quices), dudo mucho que tenga conocimientos acerca del curso. Lastima dinero que se desperdicia pagándole a este señor.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-12-03T00:00:00+00:00'::TIMESTAMPTZ, '5e7a263eda23fd5cfbbfdccabed66df9c4ad505f41468f883c278a45233d52d3'::TEXT, ARRAY[949]::BIGINT[]),
    (85::BIGINT, 'la palabra malo le queda grande, un profesor como estos no debería estar dando clases es pésimamente malo. Si usted lleva clases con el, después no va encontrar otro profe mas malo. Es una lastima que un salario se desperdicie con este profe'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas']::TEXT[], '2017-11-28T00:00:00+00:00'::TIMESTAMPTZ, '800ebdc4378a3117a0cfce4987d4525595cf883563b3e62ff06c6b90ef49c317'::TEXT, ARRAY[949]::BIGINT[]),
    (85::BIGINT, 'Es pésimo, lo que explica no es de acuerdo al curso. No se aprende nada y todo lo saca de Internet. Contesta los correos cuando se le ocurre y nunca está en la oficina.'::TEXT, 10.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Exámenes retadores', 'Muchos proyectos grupales']::TEXT[], '2017-11-22T00:00:00+00:00'::TIMESTAMPTZ, '07d3cda88978897d67dc9bb5aff97c7d3d703f6a2a281adbc0c42222da16296e'::TEXT, ARRAY[949]::BIGINT[]),
    (85::BIGINT, 'El profe no explica nada desde el inicio, para el final ya no se entiende nada, muy probablemente todos pasen porque califica fácil, pero no se va a aprender nada'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-19T00:00:00+00:00'::TIMESTAMPTZ, 'e61d82f2c53a87170f4e7e1099ff52e9726f39845b8c15d2c4cd9caeaa20499c'::TEXT, ARRAY[949]::BIGINT[]),
    (85::BIGINT, 'Da miedo...'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Clases excelentes']::TEXT[], '2017-11-09T00:00:00+00:00'::TIMESTAMPTZ, '28e2dc4f733d1b3514053a3a24baae17fcbd9e40cef5eb7d0d6e82e5192b394f'::TEXT, ARRAY[949]::BIGINT[]),
    (85::BIGINT, 'Jamas en la vida va existir un profe tan malo... No sabe lo que explica.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2017-11-05T00:00:00+00:00'::TIMESTAMPTZ, '0f5c7e566addaa8819f73d9aa01c8061a1f08e81caa17df1f66fd95573415094'::TEXT, ARRAY[949]::BIGINT[]),
    (85::BIGINT, 'Se confunde mucho en la clase y no deja clara la materia pero al menos intenta explicar algo. A veces ni él sabe lo que está haciendo. Por lo mismo los exámenes se hacen complicados pero el curso creo que es pasable.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-10-07T00:00:00+00:00'::TIMESTAMPTZ, 'd9aceaffeed0f9d47de308b4f4fca88da26e5fad5131aa40eca09953943df81a'::TEXT, ARRAY[949]::BIGINT[]),
    (85::BIGINT, 'Muy buena clase... Excelente profe'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'La participación importa']::TEXT[], '2017-07-13T00:00:00+00:00'::TIMESTAMPTZ, 'f9e6e44d4c3624628aef13d7e6b3cd5bfcd212ab7e694018e276ed460dfcb326'::TEXT, ARRAY[1205]::BIGINT[]),
    (85::BIGINT, 'Excelente profesor, entiende que es un curso muy pesado por lo que realiza una dinámica de investigación en el curso por lo que deja todo para la casa.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Requiere mucha lectura', 'Brinda apoyo']::TEXT[], '2017-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'ede6347dccfcb0eb08bf100e2e42148b57c0d29299093ae34c0edb89893759bb'::TEXT, ARRAY[1205]::BIGINT[]),
    (85::BIGINT, 'No va a aprender nada pero se pasa fácil'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'ab0c3742ce83664e77127497cfd08aa958a57f5fd47bec094a3198a7474ffeb8'::TEXT, ARRAY[949]::BIGINT[]),
    (85::BIGINT, 'Una palabra... Easy'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'e05c499fa30cdc31a2135273704cd133f809daad2aaf70c84629b4b09cdca585'::TEXT, ARRAY[949]::BIGINT[]),
    (85::BIGINT, 'Es una excelente persona, pero como profe se aprende poco, deja todo para la casa y muy sencillo.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-17T00:00:00+00:00'::TIMESTAMPTZ, '17865490ae8559f2abc86e0c6a119db73f19a0c9234b5434262f1f858ab20fb1'::TEXT, ARRAY[1205]::BIGINT[]),
    (85::BIGINT, 'Deja un proyecto sobre el desperdicio de material de alguna empresa, pero no es nada del otro mundo. Muy fácil.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Brinda apoyo']::TEXT[], '2017-06-13T00:00:00+00:00'::TIMESTAMPTZ, '103df3c178db5a799a2ae8930e5c4f0fc1aa818b6e8b8e480ba71a6e669bc9af'::TEXT, ARRAY[1205]::BIGINT[]),
