    (85::BIGINT, 'buena persona, además de una gran convivencia con los estudiantes, el curso exige trabajos escritos largos, pero en los laboratorios el intenta que todos participen para que tengan la experiencia, no califica duro, es flexible con respecto a las asistencia y reposiciones de quices o lab''s'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Aspectos de calificación claros']::TEXT[], '2016-11-28T00:00:00+00:00'::TIMESTAMPTZ, '94900b7af6547f7ef11d8ec6be1f34e358d18135ecba0e2dd95d0c472ab9d43a'::TEXT, ARRAY[2743]::BIGINT[]),
