    (85::BIGINT, 'Hace lo que le da gana con los estudiantes.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-24T00:00:00+00:00'::TIMESTAMPTZ, '4f89014f42103850ced5de0cced2d1d05de6eb05468821867153b6313e1c72a9'::TEXT, ARRAY[952]::BIGINT[]),
    (85::BIGINT, 'No es tan malo pero uno solo aprende lo básico y a puro huevo del libro. Se pasa fácilmente'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-28T00:00:00+00:00'::TIMESTAMPTZ, 'bc0e3d2e180acc16083166002cf0a4b821173bb6e7d7b02d69703c56d31bfd67'::TEXT, ARRAY[952]::BIGINT[]),
