    (85::BIGINT, 'Le gusta cambiar las clases y las hace dinámicas'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-03T00:00:00+00:00'::TIMESTAMPTZ, '0a87c4369f8ee61e1147fad6d2b4f7760ca05b3ec4ff4d4ab0d8d40329220b87'::TEXT, ARRAY[952]::BIGINT[]),
    (85::BIGINT, 'Buen profesor agradables y entretenidas clases'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Deja trabajos largos']::TEXT[], '2015-07-20T00:00:00+00:00'::TIMESTAMPTZ, '51280027fbfdda93b3e4d0c985173b6d51866ce317b02a5e27df754f788b7a07'::TEXT, ARRAY[952]::BIGINT[]),
    (85::BIGINT, 'Ni siquiera hace èl las ppt que presenta en clase, la plagia de internet'::TEXT, 8.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-07-01T00:00:00+00:00'::TIMESTAMPTZ, '9dfc03341c524cc5e1f521b04fb6457a1f9610101ffc67bfaa3353924f6d8d41'::TEXT, ARRAY[2755]::BIGINT[]),
    (85::BIGINT, 'Solo recomendado para laboratorio de tecnología de materiales, es demasiado fácil, pero no se aprende nada.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-28T00:00:00+00:00'::TIMESTAMPTZ, '1929f800514813749fe957a4a30d43d3dca7cceea8ed09808f2776e5bf598d7f'::TEXT, ARRAY[938]::BIGINT[]),
    (85::BIGINT, 'Da miedo, como dice él.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-29T00:00:00+00:00'::TIMESTAMPTZ, '0f3dbee2ca188066f60ca1953646c1d87b7dbfa5416356d67b84fe6b86bdd21a'::TEXT, ARRAY[952]::BIGINT[]),
    (85::BIGINT, 'Si quiere ser mediocre este es el profesor, aunque sea cierto que es super facil pasar con el, no se aprende nada y despues se les pasa la factura'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'a8ea35a0a298cc878d4d24b537f2d2b5068ea09c361b15ed7a60cdbb1f670757'::TEXT, ARRAY[2755]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
